import { test, expect } from '@playwright/test';

test.describe('Modal Backdrop Close Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-dialog');
  });

  test('should close modal when backdrop is clicked', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modalContainer = page.locator('[data-testid="modal-container"]');
    await expect(modalContainer).toBeVisible();

    // Verify modal title is displayed
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Verify modal content is visible
    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).toBeVisible();

    // Click on the backdrop to close the modal
    const backdrop = page.locator('[data-testid="modal-backdrop"]');
    await backdrop.click();

    // Verify modal is no longer visible
    await expect(modalContainer).not.toBeVisible();

    // Verify modal content is no longer visible
    await expect(modalContent).not.toBeVisible();

    // Verify modal title is no longer visible
    await expect(modalTitle).not.toBeVisible();
  });

  test('should not close modal when backdrop is clicked while modal is not open', async ({ page }) => {
    // Verify modal is not visible initially
    const modalContainer = page.locator('[data-testid="modal-container"]');
    await expect(modalContainer).not.toBeVisible();

    // Verify modal title is not visible initially
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).not.toBeVisible();

    // Click on the backdrop when modal is closed
    const backdrop = page.locator('[data-testid="modal-backdrop"]');
    await backdrop.click();

    // Verify modal is still not visible
    await expect(modalContainer).not.toBeVisible();

    // Verify modal title is still not visible
    await expect(modalTitle).not.toBeVisible();

    // Verify modal content is still not visible
    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).not.toBeVisible();
  });
});
